head.script:
scwin.onpageload = function() {
    var dataListArr = $p.data.getAllDataCollection();
    for (var i = 0; i < dataListArr.length; i++) {
        scwin.setData(dataListArr[i]);
    }
    scwin.setMultiLine();
};
scwin.setData = function(dataListId) {
    var data = [];
    var dataListComp = $p.getComponentById(dataListId);
    if (dataListComp.initializeType === "dataList") {
        var colCnt = dataListComp.getColumnCount();
        for (var i = 0; i < 20; i++) {
            for (var j = 0; j < colCnt; j++) {
                data.push((i + 1) * j);
            }
        }
        dataListComp.setData(data);
    } else if (dataListComp.initializeType === "dataMap") {
        var colCnt = dataListComp.getCount();
        for (var j = 0; j < colCnt; j++) {
            data.push(j);
        }
        dataListComp.setArray(data);
    }
}
scwin.isPrime = function(num) {
    for (var i = 2; i < num; i++) {
        if (num % i === 0) {
            return false;
        }
    }
    return num > 1;
}
scwin.setMultiLine = function() {
    var rowCnt = orderList.getRowCount();
    var dataStr = "aaaaaaaaaaaaaaaaabbbbbbbbbbbcccccccccccc\n";
    for (var a = 0; a < 4; a++) {
        dataStr += dataStr;
    }
    for (var i = 0; i < rowCnt; i++) {
        if (scwin.isPrime(i + 2)) {
            orderList.setCellData(i, "mprscRefMatr", dataStr);
        }
    }
}
scwin.onpageunload = function() {};
scwin.dragstart = function(startRowindex) {
    return;
    console.log("startRowindex값" + startRowindex);
    scwin.startRowindex = startRowindex;
    scwin.selRowData = [];
    scwin.delRowIndex = [];
    var samedata;
    var samedataindex = [];
    var samefocus = grd_orderList.getAllFocusedIndex();
    // 삭제(이동) 대상 index 저장
    for (var i = 0; i < samefocus.length; i++) {
        if (orderList.getCellData(samefocus[i].row, "prscCd") == "txt") {
            com.alert("전체지시사항은 옮길 수 없습니다.");
            return;
        }
        if (orderList.getCellData(samefocus[i].row, "prscCd") == "") {
            com.alert("비어있는 줄은 옮길 수 없습니다.");
            return;
        }
        if (((scwin.delRowIndex).indexOf(samefocus[i].row)) == -1) {
            scwin.delRowIndex.push(samefocus[i].row);
        }
    }
    for (var i = 0; i < samefocus.length; i++) {
        samedata = orderList.getCellData(samefocus[i].row, "prscBndl");
        if (samedata != "") {
            samedataindex = orderList.getMatchedIndex("prscBndl", samedata, true, 0, orderList.getTotalRow());
            for (var j = 1; j < samedataindex.length; j++) {
                if (((scwin.delRowIndex).indexOf(samedataindex[j])) == -1) {
                    scwin.delRowIndex.push(samedataindex[j]);
                }
            }
        }
    }
    // 삭제(이동) 대상 index 소트
    scwin.delRowIndex.sort(function(a, b) {
        return a - b;
    });
    for (var i = 0; i < scwin.delRowIndex.length; i++) {
        scwin.selRowData.push(orderList.getRowJSON(scwin.delRowIndex[i]));
    }
};
scwin.dragend = function(endRowindex) {
    return;
    if (endRowindex == orderList.getTotalRow() && orderList.getCellData(0, "prscCd") == "txt") {
        com.alert("전체지시사항은 옮길 수 없습니다.");
        return;
    }
    if (isNaN(endRowindex)) {
        return;
    }
    orderList.setBroadcast(false);
    var pk = orderList.getCellData(endRowindex, "seq");
    var totalpix = orderList.getTotalRow();
    if (scwin.selRowData == null || scwin.selRowData == []) return;
    if (scwin.startRowindex == endRowindex && scwin.delRowIndex.length == 1) return;
    // 삭제
    orderList.removeRows(scwin.delRowIndex);
    // 삽입할 위치의 index 구하기
    var insRow = "";
    var seqpls = "";
    if (orderList.getMatchedIndex("seq", pk, true) == "") {
        for (var i = 0; i < orderList.getTotalRow(); i++) {
            if ((orderList.getMatchedIndex("seq", pk - (100 * (i + 1)), true))[0] != "undefined") {
                insRow = orderList.getMatchedIndex("seq", pk - (100 * (i + 1)), true);
                seqpls = orderList.getCellData(insRow, "seq");
                break;
            }
        }
    } else {
        insRow = orderList.getMatchedIndex("seq", pk, true);
        seqpls = orderList.getCellData(insRow, "seq");
    }
    var seqrowpls;
    //if (insRow.length == 1) {
    for (var i = 0; i < scwin.selRowData.length; i++) {
        if (endRowindex == totalpix) {
            orderList.setRowJSON(0 + i, scwin.selRowData[i], false);
            if ((orderList.getCellData(0 + i, "slipSqno")).length > 0) {
                orderList.modifyRowStatus(0 + i, "U");
            }
        } else {
            orderList.setRowJSON(insRow[0] + i + 1, scwin.selRowData[i], false);
            if ((orderList.getCellData(insRow[0] + i + 1, "slipSqno")).length > 0) {
                orderList.modifyRowStatus(insRow[0] + i + 1, "U");
            }
        }
    }
    scwin.selRowData = [];
    scwin.selRowData.length = 0;
    scwin.delRowIndex = [];
    grd_orderList.removeFocusedCell();
    grd_orderList.clearCellVisible(); //추가
    orderList.setBroadcast(true, true); //위치 이동
    var chkColumnStr = "extChkRow,mprscRefMatr,extRow2";
    com.chkMultiCellVisible(grd_orderList, "mprscRefMatr", chkColumnStr);
    scwin.seqsort();
};
scwin.seqsort = function(e) {
    return;
    var seqdata = "0";
    var seqsta = "";
    for (var j = 0; j < orderList.getTotalRow(); j++) {
        seqdata = 100 * (j + 1);
        seqsta = orderList.getRowStatus(j);
        orderList.setCellData(j, "seq", seqdata);
        if (seqsta == "R") {
            orderList.setCellData(j, "rowStatus", "R");
        }
    }
};
scwin.grd_orderList_onscrollx = function() {
    //grd_orderList.setFixedColumn(14);
};
